    def search_books_by_title_author_isbn(self, query: str = None) -> List[models.Book]:
        books = self._store.all(self.ENTITY)
        books = [
            models.Book(**record)
            for record in books
            if (
                query.lower() in record.get("title", "").lower() or
                query.lower() in record.get("author_id", "").lower() or
                query.lower() in record.get("isbn", "").string()
            )
        ]
        return books
